  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: The Ascension and the Day of Pentecost$j$, $j${"questions": [{"q": "Who wrote the book of Acts?", "options": ["Luke", "Peter", "Paul", "John"]}, {"q": "According to Acts 1:8, what would the disciples receive when the Holy Ghost came upon them?", "options": ["Wealth", "A new law", "Power", "A king"]}, {"q": "On the day of Pentecost, what did the believers do when they were filled with the Holy Ghost?", "options": ["They left Jerusalem at once", "They spoke with other tongues as the Spirit gave them utterance", "They built a temple", "They kept silent"]}, {"q": "About how many souls were added to the church on the day Peter preached?", "options": ["Twelve", "One hundred and twenty", "Three thousand", "Five hundred"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: The Ascension and the Day of Pentecost$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,1,2}'::int[], array[$j$Luke wrote Acts as a second volume to his Gospel.$j$,$j$Jesus said they would receive power and be witnesses.$j$,$j$Acts 2:4 describes this event.$j$,$j$Acts 2:41 says about three thousand souls were added.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: The Ascension and the Day of Pentecost$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Peter, Stephen and the Conversion of Saul$j$, $j${"questions": [{"q": "In whose name did Peter tell the lame man to rise up and walk?", "options": ["Jesus Christ of Nazareth", "David", "Moses", "John the Baptist"]}, {"q": "What did Peter say about salvation in Acts 4:12?", "options": ["It comes through the law alone", "There is none other name under heaven whereby we must be saved", "It is found in the temple", "It is for Israel only"]}, {"q": "Who was the first Christian martyr?", "options": ["Barnabas", "Ananias", "Stephen", "James"]}, {"q": "What happened to Saul on the road to Damascus?", "options": ["He lost his way", "He was arrested", "He left for Rome", "He met the risen Jesus in a great light and was changed"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Peter, Stephen and the Conversion of Saul$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,2,3}'::int[], array[$j$Peter said, In the name of Jesus Christ of Nazareth rise up and walk (Acts 3:6).$j$,$j$Peter declared that salvation is in the name of Jesus.$j$,$j$Stephen was stoned after he preached to the council.$j$,$j$Jesus appeared to Saul, who became the apostle Paul (Acts 9).$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Peter, Stephen and the Conversion of Saul$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: The Gospel Goes to the Gentiles$j$, $j${"questions": [{"q": "What is a Gentile?", "options": ["A Roman soldier", "A priest", "A person who is not Jewish", "A teacher of the law"]}, {"q": "Who was Cornelius?", "options": ["A Roman centurion in Caesarea", "A fisherman from Galilee", "A Pharisee in Jerusalem", "A prophet in Antioch"]}, {"q": "What did Peter say about God in Acts 10:34?", "options": ["God requires the law first", "God has left the earth", "God is only for Israel", "God is no respecter of persons"]}, {"q": "Where were the disciples first called Christians?", "options": ["Damascus", "Jerusalem", "Rome", "Antioch"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The Gospel Goes to the Gentiles$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,3}'::int[], array[$j$A Gentile is a person who is not Jewish.$j$,$j$Cornelius was a devout Roman centurion in Caesarea (Acts 10:1 and 2).$j$,$j$Peter learned that God accepts people from every nation.$j$,$j$Acts 11:26 says they were called Christians first in Antioch.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The Gospel Goes to the Gentiles$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Paul's Journeys and the Witness to Rome$j$, $j${"questions": [{"q": "What did Paul and Silas do at midnight in the prison at Philippi?", "options": ["They wrote a letter to Rome", "They prayed and sang praises to God", "They argued with the guards", "They tried to escape"]}, {"q": "What did Paul tell the jailer to do to be saved?", "options": ["Believe on the Lord Jesus Christ", "Leave the city", "Keep the law", "Pay a fine"]}, {"q": "Why were the people of Berea called more noble?", "options": ["They were rich", "They built a synagogue", "They searched the Scriptures daily to see whether Paul's teaching was true", "They never sinned"]}, {"q": "In which city does the book of Acts end?", "options": ["Rome", "Athens", "Antioch", "Jerusalem"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Paul's Journeys and the Witness to Rome$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,2,0}'::int[], array[$j$Acts 16:25 says they prayed and sang praises unto God.$j$,$j$Acts 16:31 gives this answer.$j$,$j$Acts 17:11 praises them for receiving the word and searching the Scriptures.$j$,$j$Acts ends with Paul preaching in Rome.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Paul's Journeys and the Witness to Rome$j$ on conflict (item_id) do nothing;
